        combination+=1;
      }
      combination-=1;
    }
    if (combination < 0) {
      combination=Long.MAX_VALUE - 1;
    }
    return combination;
  } catch (NullPointerException e) {
    throw new RuntimeException("Failed to calculate cuboid combination due to null pointer", e);
  } catch (RuntimeException e) {
    throw new RuntimeException("Failed to calculate cuboid combination", e);
  }
}
